<?php require_once dirname(__DIR__).'/includes/site.php';$s=db()->prepare("SELECT * FROM posts WHERE slug=? AND status='published' LIMIT 1");$s->execute([preg_replace('/[^a-z0-9-]/','',$_GET['slug']??'')]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Post not found');}site_header($p['meta_title']?:$p['title'],$p['meta_description']?:$p['excerpt']);page_banner('Premium Insights',$p['title'],date('d F Y',strtotime($p['published_at'])));?><article class="section"><div class="container content"><?php if($p['featured_image']):?><img class="product-image" src="<?=UPLOAD_URL.e($p['featured_image'])?>" alt="<?=e($p['title'])?>"><?php endif?><div class="article-copy"><?=nl2br(e($p['content']))?></div></div></article><?php site_footer();
